package erratum

import "fmt"

func Use(opener ResourceOpener, input string) error {
	var resource Resource
	for {
		var err error
		resource, err = opener()
		if err == nil {
			break
		}
		// A TransientError means the resource is temporarily unavailable,
		// so retry opening it. Any other error is fatal.
		if _, ok := err.(TransientError); !ok {
			return err
		}
	}

	// Make sure the resource is closed exactly once, no matter what happens.
	// Deferred calls run when Use returns, i.e. after Frob (and any Defrob)
	// have completed.
	defer resource.Close()

	var err error
	func() {
		defer func() {
			rec := recover()
			if rec == nil {
				return
			}
			switch fe := rec.(type) {
			case FrobError:
				resource.Defrob(fe.defrobTag)
				err = fe
			case *FrobError:
				resource.Defrob(fe.defrobTag)
				err = fe
			case error:
				err = rec.(error)
			default:
				err = fmt.Errorf("%v", rec)
			}
		}()
		resource.Frob(input)
	}()
	return err
}
